static int SumSquares(int n)
{
    int total = 0;
    for (int i = 1; i <= n; i++)
        total += i * i;
    return total;
}

static int FullBatches(int stock)
{
    int batches = 0;
    while (stock >= 4)
    {
        stock -= 4;
        batches++;
    }
    return batches;
}

static int Attempts(bool ready, int retries)
{
    int attempts = 0;
    do
    {
        attempts++;
    } while (!ready && attempts <= retries);
    return attempts;
}

