Activities.SolutionCode:
public class WalletRejectionTests
{
    [Theory]
    [InlineData(5, 2, 4)]
    [InlineData(5, 1, 0)]
    [InlineData(8, 3, -1)]
    public void FailedWithdrawalPreservesUpdatedBalance(int initial, int accepted, int rejected)
    {
        var wallet = new Wallet(initial);
        Assert.True(wallet.TryWithdraw(accepted));
        Assert.False(wallet.TryWithdraw(rejected));
        Assert.Equal(initial - accepted, wallet.Balance);
    }
}

