using System.Diagnostics.CodeAnalysis;

static bool TryMarker(string? raw, [NotNullWhen(true)] out string? value)
{
    value = null;
    string? text = raw?.Trim();
    if (text is null || text.Length < 2 || text[0] != '#')
        return false;

    string marker = text[1..].Trim();
    if (marker.Length == 0)
        return false;

    value = marker;
    return true;
}

