sealed record Item(int Value);

sealed class TestResponse(string key) : HttpMessageHandler
{
    protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken token)
    {
        token.ThrowIfCancellationRequested();
        var status = key switch
        {
            "missing" => HttpStatusCode.NotFound,
            "failed" => HttpStatusCode.ServiceUnavailable,
            _ => HttpStatusCode.OK
        };
        string json = key == "ready" ? "{\"value\":6}" : "null";
        return Task.FromResult(new HttpResponseMessage(status)
        {
            Content = new StringContent(json, Encoding.UTF8, "application/json")
        });
    }
}

