static async Task<Item?> ReadAsync(HttpClient http, CancellationToken token)
{
    using var response = await http.GetAsync("https://example.test/item", token);
    if (response.StatusCode == HttpStatusCode.NotFound)
        return null;

    response.EnsureSuccessStatusCode();
    return await response.Content.ReadFromJsonAsync<Item>(cancellationToken: token)
        ?? throw new InvalidDataException("Missing item in successful response");
}

