static bool FromSplit(string text)
{
    string[] parts = text.Split('=', 2);
    return parts.Length == 2 && !string.IsNullOrWhiteSpace(parts[0])
        && int.TryParse(parts[1], out _);
}

static bool FromSpan(string text)
{
    ReadOnlySpan<char> input = text.AsSpan();
    int separator = input.IndexOf('=');
    return separator > 0 && !input[..separator].Trim().IsEmpty
        && int.TryParse(input[(separator + 1)..], out _);
}

