string text = "zone=8";
var split = ParseSplit(text);
var span = ParseSpan(text);
Console.WriteLine($"{split.Ok},{span.Ok}");
Console.WriteLine(split.Value == span.Value);

static (bool Ok, int Value) ParseSplit(string text)
{
    string[] parts = text.Split('=', 2);
    if (parts.Length != 2 || !int.TryParse(parts[1], out int number))
        return (false, 0);
    return (true, number);
}

static (bool Ok, int Value) ParseSpan(string text)
{
    int separator = text.IndexOf('=');
    if (separator < 0 || !int.TryParse(text.AsSpan(separator + 1), out int number))
        return (false, 0);
    return (true, number + 1);
}

