static bool TryValue(ReadOnlySpan<char> input, out int value)
{
    value = 0;
    int separator = input.IndexOf('=');
    if (separator <= 0 || input[..separator].Trim().IsEmpty)
        return false;

    return int.TryParse(input[(separator + 1)..], NumberStyles.Integer,
        CultureInfo.InvariantCulture, out value);
}

