sealed class Numbers : IObservable<int>
{
    private event Action<int>? Next;

    public void Publish(int value) => Next?.Invoke(value);

    public IDisposable Subscribe(IObserver<int> observer)
    {
        Next += observer.OnNext;
        return new Subscription(() => Next -= observer.OnNext);
    }
}

sealed class Subscription(Action detach) : IDisposable
{
    private Action? _detach = detach;
    public void Dispose() => Interlocked.Exchange(ref _detach, null)?.Invoke();
}

sealed class Counter(Action onValue) : IObserver<int>
{
    public void OnNext(int value) => onValue();
    public void OnCompleted() { }
    public void OnError(Exception error) { }
}

