using System.Collections.Concurrent;

var queue = Channel.CreateBounded<(int Index, int Value)>(4);
queue.Writer.TryWrite((0, 4));
queue.Writer.TryWrite((0, 4));
queue.Writer.TryWrite((1, 7));
queue.Writer.TryWrite((0, 6));
queue.Writer.TryComplete();
ITransform transform = new AboveTwo();
var results = new ConcurrentDictionary<int, int>();
var token = CancellationToken.None;

try
{
    /* پاسخ این مرحله */
}
catch (InvalidDataException)
{
    Console.WriteLine("conflict");
}
Console.WriteLine(results[0]);
Console.WriteLine(results.TryGetValue(1, out int other) ? other : -1);

public interface ITransform { int Apply(int value); }
public sealed class AboveTwo : ITransform
{
    public int Apply(int value) => value > 2 ? value : 0;
}

Activities.SolutionCode:
await foreach (var item in queue.Reader.ReadAllAsync(token))
{
    int value = transform.Apply(item.Value);
    if (results.TryAdd(item.Index, value))
        continue;

    if (results[item.Index] != value)
        throw new InvalidDataException("Conflicting work");
}

